css:
div[aria-label="Log\ lines"] > div.sz > div.row.is-error {
  background: rgba(248, 81, 73, 0.15) !important;
  box-shadow: inset 3px 0 0 rgb(248, 81, 73);
}

js:
morse.watch('div[aria-label="Log\\ lines"] > div.sz > div.row', (el) => {
  const lv = el.querySelector('span.lv');
  el.classList.toggle('is-error', !!lv && lv.textContent.trim() === 'ERROR');
}, { live: true });
